// [WSCoop] Headless host: the process's own local controller stays a pawnless spectator
// (no character creation, no save registration).
if (NewPlayer != nullptr && NewPlayer.IsLocalController() && WSDS::IsHeadlessHost())
{
    WSDS::Info("Headless host local controller kept as spectator");
    NewPlayers.RemoveAtSwap(Idx);
    continue;
}
// [WSCoop] Anonymous (direct-IP) clients must report their identity before we can decide
// between loading their character and character creation. Wait for it (first joins can spend
// minutes compiling shaders before the client finishes loading and reports).
if (NewPlayer != nullptr && WSIdentity::IsAnonymous(NewPlayer))
{
    UWSIdentityComponent IdComp = WSIdentity::GetComponent(NewPlayer);
    if (IdComp != nullptr && !IdComp.bReceived)
    {
        IdComp.WaitedSeconds += DeltaSeconds;
        if (IdComp.WaitedSeconds < 300.0)
            continue;
        WSDS::Info(f"WARNING: no identity from '{NewPlayer.PlayerState.GetPlayerName()}' after 300s; using fallback save name");
    }
}

bool bEnterCharacterCreation = bForceCharacterCreation || (SaveSubsystem.IsEnabled() && !SaveSubsystem.HasPlayerSave(NewPlayer));
// [WSCoop] Unattended testing: spawn new players with a default character.
if (bEnterCharacterCreation && System::ParseParam(System::GetCommandLine(), "WSAutoCreateCharacters"))
{
    WSDS::Info(f"Auto-creating default character for '{NewPlayer.PlayerState.GetPlayerName()}' (-WSAutoCreateCharacters)");
    bEnterCharacterCreation = false;
}
